// ============================================================
// COMMON HELPERS
// ============================================================

const cn = (...classes) =>
    classes
        .filter(Boolean)
        .join(' ')


const createEmptyMetrics = () => ({
    total: 0,
    incoming: 0,
    outgoing: 0,
    received: 0,
    missed: 0,
    unique: 0,
})


const formatNumber = (value) =>
    Number(value || 0).toLocaleString('en-IN')


const toISODate = (date) =>
    [
        date.getFullYear(),
        String(
            date.getMonth() + 1
        ).padStart(2, '0'),
        String(
            date.getDate()
        ).padStart(2, '0'),
    ].join('-')


const getToday = () =>
    toISODate(new Date())


const addDays = (
    dateString,
    amount
) => {

    const date = new Date(
        `${dateString}T00:00:00`
    )

    date.setDate(
        date.getDate() + amount
    )

    return toISODate(date)
}


const formatDateLabel = (
    dateString
) => {

    if (!dateString) {
        return ''
    }

    const date = new Date(
        `${dateString}T00:00:00`
    )

    if (
        Number.isNaN(
            date.getTime()
        )
    ) {
        return dateString
    }

    return date.toLocaleDateString(
        'en-IN',
        {
            day: '2-digit',
            month: 'short',
        }
    )
}


const formatLongDateLabel = (
    dateString
) => {

    if (!dateString) {
        return ''
    }

    const date = new Date(
        `${dateString}T00:00:00`
    )

    if (
        Number.isNaN(
            date.getTime()
        )
    ) {
        return dateString
    }

    return date.toLocaleDateString(
        'en-IN',
        {
            day: '2-digit',
            month: 'short',
            year: 'numeric',
        }
    )
}


// ============================================================
// DATE RANGE
// ============================================================

const getDateRange = (
    fromDate,
    toDate
) => {

    if (
        !fromDate ||
        !toDate ||
        fromDate > toDate
    ) {
        return []
    }

    const dates = []

    const current = new Date(
        `${fromDate}T00:00:00`
    )

    const end = new Date(
        `${toDate}T00:00:00`
    )

    while (current <= end) {

        dates.push(
            toISODate(current)
        )

        current.setDate(
            current.getDate() + 1
        )
    }

    return dates
}


const getInclusiveDayCount = (
    fromDate,
    toDate
) => {

    if (
        !fromDate ||
        !toDate ||
        fromDate > toDate
    ) {
        return 0
    }

    return getDateRange(
        fromDate,
        toDate
    ).length
}


// ============================================================
// NORMALIZE BACKEND TREND ROW
// ============================================================

const normalizeTrendRow = (
    row
) => {

    return {

        date:
            row?.date ||
            '',

        employeeContextId:
            row?.employeeContextId ??
            row?.employee_context_id ??
            row?.agentContextId ??
            row?.agent_context_id ??
            row?.rmContextId ??
            row?.rm_context_id ??
            null,

        employeeId:
            row?.employeeId ??
            row?.employee_id ??
            null,

        employeeName:
            row?.employeeName ||
            row?.employee_name ||
            row?.agentName ||
            row?.agent_name ||
            row?.rmName ||
            row?.rm_name ||
            'Unknown',

        total:
            Number(
                row?.total || 0
            ),

        incoming:
            Number(
                row?.incoming ||
                row?.received_calls ||
                0
            ),

        outgoing:
            Number(
                row?.outgoing ||
                row?.called ||
                row?.called_calls ||
                0
            ),

        received:
            Number(
                row?.received || 0
            ),

        missed:
            Number(
                row?.missed || 0
            ),

        unique:
            Number(
                row?.unique || 0
            ),
    }
}


// ============================================================
// BUILD TREND MODEL
// ============================================================

const buildTrendModel = (
    response,
    dates
) => {

    const rows = Array.isArray(
        response?.trends
    )
        ? response.trends.map(
            normalizeTrendRow
        )
        : []


    // ========================================================
    // ENTITY MAP
    // ========================================================

    const entityMap = {}


    rows.forEach((row) => {

        if (
            row.employeeContextId ===
            null ||
            row.employeeContextId ===
            undefined
        ) {
            return
        }

        const id = String(
            row.employeeContextId
        )


        if (!entityMap[id]) {

            entityMap[id] = {

                id,

                contextId:
                    row.employeeContextId,

                employeeId:
                    row.employeeId,

                name:
                    row.employeeName,
            }
        }
    })


    const entities =
        Object.values(entityMap)


    // ========================================================
    // DATE + CONTEXT MAP
    // ========================================================

    const byDate = {}


    rows.forEach((row) => {

        if (!row.date) {
            return
        }

        if (
            row.employeeContextId ===
            null ||
            row.employeeContextId ===
            undefined
        ) {
            return
        }


        const entityId =
            String(
                row.employeeContextId
            )


        if (!byDate[row.date]) {
            byDate[row.date] = {}
        }


        byDate[row.date][
            entityId
        ] = {

            total:
                row.total,

            incoming:
                row.incoming,

            outgoing:
                row.outgoing,

            received:
                row.received,

            missed:
                row.missed,

            unique:
                row.unique,
        }
    })


    // ========================================================
    // ENTITY PERIOD TOTALS
    // ========================================================
    // EntityPerformanceChart expects each entity to have a
    // `metrics` object containing totals for the selected date
    // range. Build that aggregate from the per-day data.
    const entitiesWithMetrics = entities.map((entity) => {
        const metrics = createEmptyMetrics()

        Object.values(byDate).forEach((dayEntities) => {
            const dayMetrics = dayEntities[entity.id]

            if (!dayMetrics) {
                return
            }

            metrics.total += Number(dayMetrics.total || 0)
            metrics.incoming += Number(dayMetrics.incoming || 0)
            metrics.outgoing += Number(dayMetrics.outgoing || 0)
            metrics.received += Number(dayMetrics.received || 0)
            metrics.missed += Number(dayMetrics.missed || 0)
            metrics.unique += Number(dayMetrics.unique || 0)
        })

        return {
            ...entity,
            metrics,
        }
    })


    // ========================================================
    // DAILY DATA
    // ========================================================

    // ========================================================
    // DAILY DATA
    // ========================================================

    const trendData =
        dates.map((date) => {

            const entityMetrics =
                byDate[date] || {}


            const summary =
                createEmptyMetrics()


            Object.values(
                entityMetrics
            ).forEach(
                (metrics) => {

                    summary.total +=
                        metrics.total

                    summary.incoming +=
                        metrics.incoming

                    summary.outgoing +=
                        metrics.outgoing

                    summary.received +=
                        metrics.received

                    summary.missed +=
                        metrics.missed

                    summary.unique +=
                        metrics.unique
                }
            )


            return {

                date,

                metrics:
                    entityMetrics,

                summary,
            }
        })


    // ========================================================
    // Y AXIS
    // ========================================================

    const maxValue =
        Math.max(
            1,
            ...trendData.map(
                (day) =>
                    Number(
                        day.summary.total ||
                        0
                    )
            )
        )


    const yStep =
        Math.max(
            Math.ceil(
                maxValue / 5
            ),
            1
        )


    const yMax =
        yStep * 5


    return {

        entities: entitiesWithMetrics,

        trendData,

        yStep,

        yMax,
    }
}


