// ============================================================
// DAILY STACKED BAR CHART
// ============================================================

const DailyLineChart = memo(function DailyLineChart({
    dates,
    trendData,
    yMax,
    view,
}) {
    const [hoveredIndex, setHoveredIndex] = useState(null)

    const chartHeight = 340
    const svgWidth = 1000
    const paddingLeft = 48
    const paddingRight = 18
    const paddingTop = 24
    const paddingBottom = 42
    const plotWidth = svgWidth - paddingLeft - paddingRight
    const plotHeight = chartHeight - paddingTop - paddingBottom

    const safeMax = Math.max(1, Number(yMax || 0))
    const tickStep = safeMax > 5
        ? Math.ceil(safeMax / 5)
        : 1
    const ticks = Array.from(
        { length: 6 },
        (_, index) => Math.max(0, tickStep * (5 - index))
    )

    const maxTick = Math.max(safeMax, ticks[0])

    const getX = (index) => {
        if (dates.length <= 1) {
            return paddingLeft + plotWidth / 2
        }

        return (
            paddingLeft +
            (index / (dates.length - 1)) * plotWidth
        )
    }

    const getY = (value) => {
        const ratio = maxTick > 0
            ? Number(value || 0) / maxTick
            : 0

        return paddingTop + (1 - ratio) * plotHeight
    }

    const buildPath = (key) => {
        if (!trendData.length) {
            return ''
        }

        return trendData
            .map((day, index) => {
                const x = getX(index)
                const y = getY(day.summary[key])
                return `${index === 0 ? 'M' : 'L'} ${x} ${y}`
            })
            .join(' ')
    }

    const hoveredDay =
        hoveredIndex !== null
            ? trendData[hoveredIndex]
            : null

    const hoveredLeft =
        hoveredIndex !== null && dates.length > 1
            ? Math.min(
                86,
                Math.max(
                    10,
                    (getX(hoveredIndex) / svgWidth) * 100
                )
            )
            : 50

    const labelIndexes = useMemo(() => {
        if (dates.length <= 8) {
            return dates.map((_, index) => index)
        }

        const targetLabels = 8
        const step = Math.ceil(
            (dates.length - 1) / (targetLabels - 1)
        )

        const indexes = []
        for (let index = 0; index < dates.length; index += step) {
            indexes.push(index)
        }

        if (indexes[indexes.length - 1] !== dates.length - 1) {
            indexes.push(dates.length - 1)
        }

        return indexes
    }, [dates])

    return (
        <div>
            <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
                <div className="flex flex-wrap items-center gap-4">
                    <LegendItem label="Total Calls" color={COLORS.line} />
                </div>

                <span className="text-[10px] text-base-content/35">
                    Hover a point for daily breakdown
                </span>
            </div>

            <div className="relative w-full min-w-0">
                <svg
                    width="100%"
                    height={chartHeight}
                    viewBox={`0 0 ${svgWidth} ${chartHeight}`}
                    preserveAspectRatio="none"
                    className="block w-full overflow-visible"
                    onMouseLeave={() => setHoveredIndex(null)}
                >
                    {ticks.map((tick) => {
                        const y = getY(tick)

                        return (
                            <g key={tick}>
                                <line
                                    x1={paddingLeft}
                                    x2={svgWidth - paddingRight}
                                    y1={y}
                                    y2={y}
                                    stroke="currentColor"
                                    strokeWidth="1"
                                    strokeDasharray="3 4"
                                    className="text-base-300"
                                />

                                <text
                                    x={paddingLeft - 10}
                                    y={y + 4}
                                    textAnchor="end"
                                    className="fill-current text-[10px] text-base-content/35"
                                >
                                    {formatNumber(tick)}
                                </text>
                            </g>
                        )
                    })}

                    <line
                        x1={paddingLeft}
                        x2={svgWidth - paddingRight}
                        y1={chartHeight - paddingBottom}
                        y2={chartHeight - paddingBottom}
                        stroke="currentColor"
                        strokeWidth="1"
                        className="text-base-300"
                    />

                    <path
                        d={buildPath('total')}
                        fill="none"
                        stroke={COLORS.line}
                        strokeWidth="3"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                    />

                    {trendData.map((day, index) => {
                        const x = getX(index)
                        const active = hoveredIndex === index

                        return (
                            <g key={day.date}>
                                <rect
                                    x={x - 7}
                                    y={paddingTop}
                                    width="14"
                                    height={plotHeight}
                                    fill="transparent"
                                    onMouseEnter={() => setHoveredIndex(index)}
                                />

                                <circle
                                    cx={x}
                                    cy={getY(day.summary.total)}
                                    r={active ? 5 : 3.5}
                                    fill={COLORS.line}
                                    stroke="white"
                                    strokeWidth="1.5"
                                    className="cursor-pointer"
                                    onMouseEnter={() => setHoveredIndex(index)}
                                />
                            </g>
                        )
                    })}

                    {labelIndexes.map((index) => (
                        <text
                            key={dates[index]}
                            x={getX(index)}
                            y={chartHeight - 12}
                            textAnchor="middle"
                            className="fill-current text-[10px] font-medium text-base-content/45"
                        >
                            {formatDateLabel(dates[index])}
                        </text>
                    ))}
                </svg>

                {hoveredDay && (
                    <div
                        className="pointer-events-none absolute top-2 z-10 w-48 -translate-x-1/2 rounded-lg border border-base-300 bg-base-100 p-3 shadow-lg"
                        style={{ left: `${hoveredLeft}%` }}
                    >
                        <div className="mb-2 flex items-center justify-between gap-2 border-b border-base-200 pb-2">
                            <span className="text-[10px] font-semibold text-base-content">
                                {formatDateLabel(hoveredDay.date)}
                            </span>
                            <span className="text-[10px] font-bold text-base-content">
                                {formatNumber(hoveredDay.summary.total)} total
                            </span>
                        </div>

                        <div className="space-y-1.5">
                            <TooltipMetric
                                label="Received"
                                value={hoveredDay.summary.received}
                                color={COLORS.received}
                            />
                            <TooltipMetric
                                label="Missed"
                                value={hoveredDay.summary.missed}
                                color={COLORS.missed}
                            />
                            <TooltipMetric
                                label="Outgoing"
                                value={hoveredDay.summary.outgoing}
                                color={COLORS.outgoing}
                            />
                            <TooltipMetric
                                label="Incoming"
                                value={hoveredDay.summary.incoming}
                            />
                            <TooltipMetric
                                label="Unique"
                                value={hoveredDay.summary.unique}
                            />
                        </div>
                    </div>
                )}
            </div>
        </div>
    )
})


// ============================================================
// ENTITY PERFORMANCE
// ============================================================

const EntityPerformanceChart = memo(function EntityPerformanceChart({
    entities,
    view,
}) {
    const [selectedId, setSelectedId] = useState(null)

    if (!entities.length) {
        return null
    }

    const maxTotal = Math.max(
        1,
        ...entities.map((entity) => entity.metrics.total)
    )

    return (
        <div className="mt-7 border-t border-base-300 pt-5">
            <div className="mb-4 flex items-center justify-between gap-3">
                <div>
                    <h3 className="text-xs font-semibold text-base-content">
                        {view === 'agent' ? 'Agent' : 'RM'} Performance
                    </h3>
                    <p className="mt-0.5 text-[10px] text-base-content/40">
                        Total calls for the selected period. Click a row for detailed metrics.
                    </p>
                </div>

                <span className="text-[10px] text-base-content/35">
                    {entities.length} {view === 'agent' ? 'agents' : 'RMs'}
                </span>
            </div>

            <div className="max-h-[420px] space-y-1.5 overflow-y-auto pr-1">
                {entities.map((entity, index) => {
                    const percentage =
                        (entity.metrics.total / maxTotal) * 100
                    const selected = selectedId === entity.id

                    return (
                        <div key={entity.id}>
                            <button
                                type="button"
                                onClick={() =>
                                    setSelectedId(selected ? null : entity.id)
                                }
                                className={cn(
                                    'w-full rounded-lg px-2.5 py-2 text-left transition',
                                    selected
                                        ? 'bg-base-200'
                                        : 'hover:bg-base-200/50'
                                )}
                            >
                                <div className="mb-1.5 flex items-center gap-3">
                                    <span className="w-5 shrink-0 text-right text-[9px] font-semibold text-base-content/30">
                                        {index + 1}
                                    </span>

                                    <span className="min-w-0 flex-1 truncate text-[10px] font-medium text-base-content">
                                        {entity.name}
                                    </span>

                                    <span className="shrink-0 text-[10px] font-bold text-base-content">
                                        {formatNumber(entity.metrics.total)}
                                    </span>
                                </div>

                                <div className="ml-8 h-2 overflow-hidden rounded-full bg-base-200">
                                    <div
                                        className="h-full rounded-full transition-all"
                                        style={{
                                            width: `${percentage}%`,
                                            backgroundColor: COLORS.incoming,
                                        }}
                                    />
                                </div>
                            </button>

                            {selected && (
                                <div className="ml-8 mt-1 mb-2 grid grid-cols-2 gap-x-5 rounded-lg border border-base-300 bg-base-100 px-3 py-2">
                                    <TooltipMetric
                                        label="Incoming"
                                        value={entity.metrics.incoming}
                                        color={COLORS.incoming}
                                    />
                                    <TooltipMetric
                                        label="Outgoing"
                                        value={entity.metrics.outgoing}
                                        color={COLORS.outgoing}
                                    />
                                    <TooltipMetric
                                        label="Received"
                                        value={entity.metrics.received}
                                        color={COLORS.received}
                                    />
                                    <TooltipMetric
                                        label="Missed"
                                        value={entity.metrics.missed}
                                        color={COLORS.missed}
                                    />
                                    <TooltipMetric
                                        label="Unique"
                                        value={entity.metrics.unique}
                                        color={COLORS.unique}
                                    />
                                </div>
                            )}
                        </div>
                    )
                })}
            </div>
        </div>
    )
})


// ============================================================
// TREND CHART WRAPPER
// ============================================================

const TrendChart = memo(function TrendChart({
    dates,
    trendData,
    entities,
    yMax,
    yStep,
    view,
}) {
    return (
        <>
            <DailyLineChart
                dates={dates}
                trendData={trendData}
                yMax={yMax}
                yStep={yStep}
                view={view}
            />

            <EntityPerformanceChart
                entities={entities}
                view={view}
            />
        </>
    )
})


// ============================================================
// EMPTY STATE
// ============================================================

const EmptyState = memo(
    function EmptyState({
        view,
    }) {

        return (
            <div className="flex h-[340px] items-center justify-center">

                <div className="text-center">

                    <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-base-200">

                        <PhoneIcon className="h-5 w-5 text-base-content/30" />

                    </div>

                    <p className="text-sm font-medium text-base-content/60">
                        No call activity
                    </p>

                    <p className="mt-1 text-xs text-base-content/40">
                        Try changing the team lead,{' '}
                        {
                            VIEW_META[
                                view
                            ].singular
                        }
                        , or date range.
                    </p>

                </div>

            </div>
        )
    }
)


// ============================================================
// MAIN COMPONENT
// ============================================================

function CallPerformanceTrend({
    contextId = '',
}) {

    // ========================================================
    // TODAY
    // ========================================================

    const today = useMemo(
        () => getToday(),
        []
    )


    // ========================================================
    // DEFAULT 3-DAY RANGE
    // ========================================================

    const defaultFromDate =
        useMemo(
            () =>
                addDays(
                    today,
                    -2
                ),
            [today]
        )


    // ========================================================
    // VIEW
    // ========================================================

    const [
        view,
        setView,
    ] = useState('agent')


    // ========================================================
    // PERFORMANCE DATA
    // ========================================================

    const [
        performanceData,
        setPerformanceData,
    ] = useState({

        summary:
            createEmptyMetrics(),

        trends: [],
    })


    // ========================================================
    // LOADING
    // ========================================================

    const [
        loading,
        setLoading,
    ] = useState(true)


    const [
        refreshing,
        setRefreshing,
    ] = useState(false)


    // ========================================================
    // FILTERS
    // ========================================================

    const [
        teamLeadContextId,
        setTeamLeadContextId,
    ] = useState('')


    const [
        agentContextId,
        setAgentContextId,
    ] = useState('')


    const [
        rmContextId,
        setRmContextId,
    ] = useState('')


    // ========================================================
    // DATES
    // ========================================================

    const [
        fromDate,
        setFromDate,
    ] = useState(
        defaultFromDate
    )


    const [
        toDate,
        setToDate,
    ] = useState(today)


    // ========================================================
    // REQUEST CONTROL
    // ========================================================

    const requestId =
        useRef(0)


    // ========================================================
    // LOAD DATA
    // ========================================================

    const loadData =
        useCallback(
            async ({
                isRefresh = false,
            } = {}) => {

                const currentRequest =
                    ++requestId.current


                const isLatest = () =>
                    currentRequest ===
                    requestId.current


                try {

                    if (
                        isRefresh
                    ) {
                        setRefreshing(
                            true
                        )
                    } else {
                        setLoading(
                            true
                        )
                    }


                    const response =
                        await fetchCallPerformanceTrend(
                            {
                                view,

                                teamLeadContextId,

                                agentContextId:
                                    view ===
                                    'agent'
                                        ? agentContextId
                                        : '',

                                rmContextId:
                                    view ===
                                    'rm'
                                        ? rmContextId
                                        : '',

                                fromDate,

                                toDate,

                                contextId,
                            }
                        )


                    if (
                        !isLatest()
                    ) {
                        return
                    }


                    setPerformanceData(
                        response || {
                            summary:
                                createEmptyMetrics(),

                            trends: [],
                        }
                    )

                } catch (
                    error
                ) {

                    console.error(
                        'Failed to load call performance trend:',
                        error
                    )


                    if (
                        isLatest()
                    ) {

                        setPerformanceData(
                            {
                                summary:
                                    createEmptyMetrics(),

                                trends: [],
                            }
                        )
                    }

                } finally {

                    if (
                        isLatest()
                    ) {

                        setLoading(
                            false
                        )

                        setRefreshing(
                            false
                        )
                    }
                }
            },
            [
                view,
                teamLeadContextId,
                agentContextId,
                rmContextId,
                fromDate,
                toDate,
                contextId,
            ]
        )


    // ========================================================
    // EFFECT
    // ========================================================

    useEffect(() => {

        loadData()

        return () => {

            requestId.current += 1

        }

    }, [loadData])


    // ========================================================
    // DATES
    // ========================================================

    const dates =
        useMemo(
            () =>
                getDateRange(
                    fromDate,
                    toDate
                ),
            [
                fromDate,
                toDate,
            ]
        )


    // ========================================================
    // TREND MODEL
    // ========================================================

    const {
        entities,
        trendData,
        yStep,
        yMax,
    } = useMemo(
        () =>
            buildTrendModel(
                performanceData,
                dates
            ),
        [
            performanceData,
            dates,
        ]
    )


    // ========================================================
    // META
    // ========================================================

    const viewMeta =
        VIEW_META[view]


    const hasData =
        trendData.some(
            (day) =>
                Number(
                    day.summary.total ||
                    0
                ) > 0
        )


    const totalCalls =
        Number(
            performanceData
                ?.summary
                ?.total || 0
        )


    // ========================================================
    // RESET
    // ========================================================

    const handleReset =
        useCallback(
            () => {

                setTeamLeadContextId(
                    ''
                )

                setAgentContextId(
                    ''
                )

                setRmContextId(
                    ''
                )

                setFromDate(
                    defaultFromDate
                )

                setToDate(
                    today
                )

            },
            [
                defaultFromDate,
                today,
            ]
        )


    // ========================================================
    // VIEW CHANGE
    // ========================================================

    const handleViewChange =
        useCallback(
            (nextView) => {

                setView(
                    nextView
                )

                setAgentContextId(
                    ''
                )

                setRmContextId(
                    ''
                )

            },
            []
        )


    // ========================================================
    // TEAM LEAD CHANGE
    // ========================================================

    const handleTeamLeadChange =
        useCallback(
            (value) => {

                setTeamLeadContextId(
                    value
                )

                setAgentContextId(
                    ''
                )

                setRmContextId(
                    ''
                )

            },
            []
        )


    // ========================================================
    // AGENT CHANGE
    // ========================================================

    const handleAgentChange =
        useCallback(
            (value) => {

                setAgentContextId(
                    value
                )

            },
            []
        )


    // ========================================================
    // RM CHANGE
    // ========================================================

    const handleRmChange =
        useCallback(
            (value) => {

                setRmContextId(
                    value
                )

            },
            []
        )


    // ========================================================
    // FROM DATE CHANGE
    // ========================================================

    const handleFromDateChange =
        useCallback(
            (nextFromDate) => {

                if (
                    !nextFromDate
                ) {
                    return
                }


                const minimumToDate =
                    addDays(
                        nextFromDate,
                        2
                    )


                setFromDate(
                    nextFromDate
                )


                if (
                    !toDate ||
                    toDate <
                        minimumToDate
                ) {

                    setToDate(
                        minimumToDate
                    )
                }

            },
            [toDate]
        )


    // ========================================================
    // TO DATE CHANGE
    // ========================================================

    const handleToDateChange =
        useCallback(
            (nextToDate) => {

                if (
                    !nextToDate
                ) {
                    return
                }


                const minimumFromDate =
                    addDays(
                        nextToDate,
                        -2
                    )


                setToDate(
                    nextToDate
                )


                if (
                    !fromDate ||
                    fromDate >
                        minimumFromDate
                ) {

                    setFromDate(
                        minimumFromDate
                    )
                }

            },
            [fromDate]
        )


    // ========================================================
    // DATE RANGE
    // ========================================================

    const selectedDayCount =
        getInclusiveDayCount(
            fromDate,
            toDate
        )


    // ========================================================
    // LOADING
    // ========================================================

    if (loading) {

        return (

            <section
                className={
                    SECTION_CLASS
                }
                aria-busy="true"
            >

                <div className="space-y-4 p-5">

                    <div className="h-10 w-56 animate-pulse rounded-lg bg-base-200" />

                    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-5">

                        {Array.from(
                            {
                                length: 5,
                            },
                            (
                                _,
                                index
                            ) => (

                                <div
                                    key={
                                        index
                                    }
                                    className="h-10 animate-pulse rounded-lg bg-base-200"
                                />

                            )
                        )}

                    </div>

                    <div className="h-[340px] animate-pulse rounded-xl bg-base-200/60" />

                </div>

            </section>
        )
    }


    // ========================================================
    // RENDER
    // ========================================================

    return (

        <section
            className={
                SECTION_CLASS
            }
        >

            {/* ==================================================
                HEADER
            ================================================== */}

            <div className="flex flex-col gap-4 border-b border-base-300 px-5 py-4 lg:flex-row lg:items-center lg:justify-between">

                <div className="flex items-center gap-3">

                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#8BCF00]/10">

                        <PhoneIcon className="h-5 w-5 text-[#6FA800]" />

                    </div>


                    <div>

                        <h2 className="text-sm font-semibold text-base-content">
                            Call Activity Trend
                        </h2>

                        <p className="mt-0.5 text-xs text-base-content/45">
                            Daily call activity with{' '}
                            {
                                view ===
                                'agent'
                                    ? 'agent-wise'
                                    : 'RM-wise'
                            }{' '}
                            breakdown.
                        </p>

                    </div>

                </div>


                <ViewTabs
                    view={view}
                    onChange={
                        handleViewChange
                    }
                />

            </div>


            {/* ==================================================
                FILTERS
            ================================================== */}

            <div className="grid grid-cols-1 gap-3 border-b border-base-300 px-5 py-4 sm:grid-cols-2 lg:grid-cols-5">

                <TeamLeadDropdown
                    label="Team Lead"
                    value={
                        teamLeadContextId
                    }
                    onChange={
                        handleTeamLeadChange
                    }
                />


                {view ===
                'agent' ? (

                    <AgentDropdown
                        label="Agent"
                        value={
                            agentContextId
                        }
                        teamLeadId={
                            teamLeadContextId
                        }
                        onChange={
                            handleAgentChange
                        }
                    />

                ) : (

                    <RmDropdown
                        label="RM"
                        value={
                            rmContextId
                        }
                        teamLeadId={
                            teamLeadContextId
                        }
                        onChange={
                            handleRmChange
                        }
                    />

                )}


                <DateInput
                    label="From"
                    value={fromDate}
                    onChange={
                        handleFromDateChange
                    }
                />


                <DateInput
                    label="To"
                    value={toDate}
                    onChange={
                        handleToDateChange
                    }
                />


                <div className="flex items-end gap-2">

                    <button
                        type="button"
                        onClick={
                            handleReset
                        }
                        disabled={
                            refreshing
                        }
                        className="
                            h-10
                            flex-1
                            rounded-lg
                            border
                            border-base-300
                            bg-base-100
                            px-3
                            text-xs
                            font-medium
                            text-base-content/60
                            transition
                            hover:bg-base-200
                            hover:text-base-content
                            disabled:opacity-60
                        "
                    >
                        Reset
                    </button>


                    <button
                        type="button"
                        onClick={() =>
                            loadData({
                                isRefresh:
                                    true,
                            })
                        }
                        disabled={
                            refreshing
                        }
                        className="
                            inline-flex
                            h-10
                            flex-1
                            items-center
                            justify-center
                            gap-1.5
                            rounded-lg
                            bg-[#8BCF00]
                            px-3
                            text-xs
                            font-medium
                            text-white
                            transition
                            hover:bg-[#78B300]
                            disabled:opacity-60
                        "
                    >

                        <ArrowPathIcon
                            className={cn(
                                'h-4 w-4',
                                refreshing &&
                                    'animate-spin'
                            )}
                        />

                        Refresh

                    </button>

                </div>

            </div>


            {/* ==================================================
                FILTER INFORMATION
            ================================================== */}

            <div className="flex flex-wrap items-center gap-x-5 gap-y-1 border-b border-base-300 px-5 py-2.5 text-[10px] text-base-content/45">

                <span>
                    View:{' '}
                    <b className="text-base-content/70">
                        {viewMeta.tab}
                    </b>
                </span>


                <span>
                    Period:{' '}
                    <b className="text-base-content/70">

                        {formatDateLabel(
                            fromDate
                        )}

                        {' — '}

                        {formatDateLabel(
                            toDate
                        )}

                    </b>
                </span>


                <span>
                    {
                        selectedDayCount
                    }{' '}
                    days
                </span>


                <span>
                    Total calls:{' '}
                    <b className="text-base-content/70">
                        {
                            formatNumber(
                                totalCalls
                            )
                        }
                    </b>
                </span>


                <span className="text-base-content/35">
                    Hover a point for detailed{' '}
                    {
                        viewMeta.singular
                    }{' '}
                    metrics
                </span>

            </div>


            {/* ==================================================
                GRAPH
            ================================================== */}

            <div className="overflow-visible px-5 py-5">

                {hasData ? (

                    <TrendChart
                        dates={dates}
                        trendData={
                            trendData
                        }
                        entities={
                            entities
                        }
                        yMax={yMax}
                        yStep={yStep}
                        view={view}
                    />

                ) : (

                    <EmptyState
                        view={view}
                    />

                )}

            </div>


            {/* ==================================================
                FOOTER
            ================================================== */}

            <div className="flex items-center justify-center gap-1.5 border-t border-base-300 py-3 text-[10px] text-base-content/35">

                <CalendarDaysIcon className="h-3.5 w-3.5" />

                Call Activity

            </div>

        </section>
    )
}


// ============================================================
// DEFAULT EXPORT
// ============================================================

export default CallPerformanceTrend